<?php
// Included by InventoryTest inside its disposable database.
$master=new App\Services\ProductMasterService(1);$brand=$master->save('brands',['name'=>'REF']);$maker=$master->save('vehicle_manufacturers',['name'=>'Bajaj Test']);$model=$master->save('vehicle_models',['manufacturer_id'=>$maker,'name'=>'REF']);$variant=$master->save('vehicle_variants',['model_id'=>$model,'name'=>'Disc']);$secondVariant=$master->save('vehicle_variants',['model_id'=>$model,'name'=>'Drum']);
$names=['Exact SKU','Exact OEM','REF','REF spare','Brand part','Bike part','Local part'];$rankIds=[];
foreach($names as $i=>$name){$d=['name'=>$name,'category_id'=>$category,'purchase_price'=>'10','selling_price'=>'20','opening_quantity'=>'3','opening_cost'=>'10','opening_date'=>'2026-01-01','reorder_level'=>'5'];
 if($i===0)$d['sku']='REF';if($i===1)$d['part_number']='REF';if($i===4)$d['brand_id']=$brand;
 if($i===5)$d['fitments']=[['manufacturer_id'=>$maker,'model_id'=>$model,'variant_id'=>$variant,'year_from'=>'2020','year_to'=>'2022'],['manufacturer_id'=>$maker,'model_id'=>$model,'variant_id'=>$secondVariant,'year_from'=>'2023','year_to'=>'2025']];
 if($i===6)$d['aliases']='REF, local slang';$rankIds[]=$productService->save($d,$owner,null,'rank-'.$i,true);
}
$search=new App\Services\InventorySearchService(1);$results=$search->listing(['q'=>'  rEf  ']);invcheck(array_map('intval',array_column($results['rows'],'id'))===$rankIds,'Search ranks exact SKU, OEM, name, partial name, brand, bike then alias');
invcheck($search->listing(['q'=>'Bajaj REF'])['total']===1,'Multi-word maker/model query uses explicit fitments');invcheck($search->listing(['q'=>'Disc'])['total']===1,'Variant names searchable');invcheck($search->listing(['q'=>'Bajaj'])['total']===1,'Manufacturer search does not duplicate matching bike mappings');invcheck($search->listing(['q'=>'  LOCAL    slang '])['total']===1,'Aliases normalize case and repeated spaces');
invcheck($search->listing(['q'=>'RE'])['total']>=7,'Partial SKU and OEM searches supported');invcheck($search->listing(['q'=>'impossible search'])['total']===0,'Empty results are explicit');
invcheck($search->listing(['manufacturer_id'=>$maker,'model_id'=>$model])['total']===1,'Model returns all matching products once');invcheck($search->listing(['model_id'=>$model,'variant_id'=>$variant,'year'=>'2021'])['total']===1,'Variant and recorded year bounds respected');invcheck($search->listing(['model_id'=>$model,'variant_id'=>$variant,'year'=>'2024'])['total']===0,'Unsupported year excluded for selected variant');invcheck($search->listing(['model_id'=>$model,'year'=>'2024'])['total']===1,'Year can match another recorded variant under the model');
invcheck($search->listing(['q'=>'REF','model_id'=>$model,'stock'=>'low','status'=>'active'])['total']===1,'Universal query combines with bike, low-stock and product-status filters');invcheck($search->listing(['q'=>'REF','stock'=>'out'])['total']===0,'Out-of-stock filter excludes positive low stock');
$inactive=$productService->save(['name'=>'Inactive balance','category_id'=>$category,'purchase_price'=>'1','selling_price'=>'2','opening_quantity'=>'4','opening_cost'=>'1','opening_date'=>'2026-01-01','status'=>'inactive'],$owner,null,'inactive-balance');$archived=$productService->save(['name'=>'Archived balance','category_id'=>$category,'purchase_price'=>'1','selling_price'=>'2','opening_quantity'=>'5','opening_cost'=>'1','opening_date'=>'2026-01-01'],$owner,null,'archived-balance');$productService->archive($archived,$owner);
$scoped=$read->overview();invcheck($scoped['inactive_units']==='4.000000' && $scoped['archived_units']==='5.000000','Inactive/archived balances shown separately');invcheck(bccomp($scoped['total_units'],bcadd(bcadd($scoped['active_units'],$scoped['inactive_units'],6),$scoped['archived_units'],6),6)===0,'All-stock total equals separated scopes');
invcheck($search->listing(['status'=>'inactive'])['total']===1 && $search->listing(['status'=>'archived'])['total']===1,'Product-status filters respect separate scopes');
for($i=0;$i<20;$i++)$productService->save(['name'=>'Pagination fixture '.str_pad((string)$i,2,'0',STR_PAD_LEFT),'category_id'=>$category,'purchase_price'=>'1','selling_price'=>'2','opening_quantity'=>'0'],$owner,null,'pagination-fixture-'.$i);
$all=$search->listing(['status'=>'all']);invcheck($all['total']>25 && count($all['rows'])===25 && $search->listing(['status'=>'all','page'=>2])['page']===2,'Server-side pagination remains bounded');
$sort=$search->listing(['q'=>'REF','sort'=>'stock','direction'=>'desc']);invcheck(count($sort['rows'])===7,'Sorting keeps ranked matches without duplication');
$selected=$read->product($rankIds[5]);invcheck($selected['category_name']!==null && $selected['quantity']==='3.000000','Adjustment selection includes category and current stock');
putenv('INVENTORY_SEARCH_FIXTURES='.json_encode(['rank_ids'=>$rankIds,'maker'=>$maker,'model'=>$model,'variant'=>$variant,'brand'=>$brand]));
